# Vault storage download sub-app mounted at: app.mount("/storage/vault", vault_subapp)
vault_subapp = FastAPI()

@vault_subapp.get("/files/{file_id}/download")
async def download_vault_file(
    file_id: str,
    storage: ObjectStorage = Depends(get_storage),
    current_user: User = Depends(get_current_user)
):
    file_meta = await storage.get_metadata(file_id)
    if not file_meta or (file_meta.tenant_id != current_user.tenant_id and not current_user.is_admin):
        raise HTTPException(status_code=404, detail="File not found or access denied")
    return StreamingResponse(
        storage.open(file_meta.path),
        media_type=file_meta.content_type
    )
